import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem113 preserva dados operacionais',()=>{for(const [n,titulo,expected,link] of [["7304557578","Cooler para Notebook Gamer Megabyte SR002 com 4 Ventoinhas e LED Azul para Laptop até 17.3\"","Base refrigeradora Megabyte SR002 com 4 ventoinhas","https://www.mercadolivre.com.br/p/MLB76169253?wid=MLB7304557578"],["7593699030","Repetidor Sinal Wifi Gigab 1200mb 2.4g Dual Band Wireles 6an","Repetidor Wi-Fi TRQ3 — dual band anunciado","https://www.mercadolivre.com.br/p/MLB2115543194?wid=MLB7593699030"],["7678487136","Perfume Masculino Vibrato 200ml Alta Fixação","Perfume masculino Monarq Vibrato — 200 mL anunciados","https://www.mercadolivre.com.br/up/MLBU5266071440"]]){const p={id:'mlMLB'+n,titulo,link,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);}});
